-- Hosbah: one stretch of a monitor failing: opened by the evaluator (internal/monitors) after 2
-- consecutive failures (http) or one evaluation over the threshold (cpu | memory | disk), resolved
-- on the first success. A monitor has at most one open incident. notified: the opening was
-- announced (team notification, email, webhook). Rows go with their monitor (and so their app).
CREATE UNIQUE INDEX monitor_incidents_open_key ON monitor_incidents (monitor_id) WHERE resolved_at IS NULL;
CREATE INDEX monitor_incidents_app_idx ON monitor_incidents (app_id, opened_at DESC, id DESC);
CREATE INDEX monitor_incidents_team_idx ON monitor_incidents (team_id);
